package vn.hust.restaurant.controller;import java.math.*;import java.sql.*;import java.time.*;import java.util.*;import vn.hust.restaurant.model.Ingredient;import vn.hust.restaurant.repository.InventoryRepository;import vn.hust.restaurant.service.InventoryService;public class InventoryController{private final InventoryService s;public InventoryController(InventoryService s){this.s=s;}public List<Ingredient>list(String k)throws SQLException{return s.list(k);}public Map<Integer,String>categories()throws SQLException{return s.categories();}public void save(Ingredient i)throws SQLException{s.save(i);}public List<InventoryRepository.Supplier>suppliers()throws SQLException{return s.suppliers();}public void supplier(InventoryRepository.Supplier x)throws SQLException{s.saveSupplier(x);}public long receive(int e,int sup,int ing,BigDecimal q,BigDecimal c,LocalDate d,String n)throws SQLException{return s.receive(e,sup,ing,q,c,d,n);}public void adjust(int e,int i,BigDecimal q,String r)throws SQLException{s.adjust(e,i,q,r);}public void recipe(int m,int i,BigDecimal a)throws SQLException{s.recipe(m,i,a);}}